List<int> intersperse(List<int> numbers, int delimeter) {
  if (numbers.isEmpty) {
    return [];
  }

  List<int> result = [];

  for (int i = 0; i < numbers.length - 1; i++) {
    result.add(numbers[i]);
    result.add(delimeter);
  }

  result.add(numbers[numbers.length - 1]);

  return result;
}

