import 'dart:math';

@pragma('vm:entry-point')
List<int> rollingMax(List<int> numbers) {
  int? runningMax;
  List<int> result = [];

  for (int n in numbers) {
    if (runningMax == null) {
      runningMax = n;
    } else {
      runningMax = max(runningMax, n);
    }

    result.add(runningMax);
  }

  return result;
}

