import 'dart:math';

@pragma('vm:entry-point')
int primeFib(int n) {
  bool isPrime(int p) {
    if (p < 2) {
      return false;
    }
    for (int k = 2; k < min(sqrt(p).toInt() + 1, p - 1); k++) {
      if (p % k == 0) {
        return false;
      }
    }
    return true;
  }

  List<int> f = [0, 1];
  while (true) {
    f.add(f[f.length - 1] + f[f.length - 2]);
    if (isPrime(f[f.length - 1])) {
      n -= 1;
    }
    if (n == 0) {
      return f[f.length - 1];
    }
  }
}

