List<int> sortArray(List<int> array) {
  if (array.isEmpty) {
    return [];
  }

  List<int> result = List.from(array);
  bool isEven = (array.first + array.last) % 2 == 0;

  if (isEven) {
    result.sort((a, b) => b.compareTo(a));
