int skjkasdkd(List<int> lst) {
  bool isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i <= sqrt(n).floor(); i++) {
      if (n % i == 0) {
        return false;
      }
    }
    return true;
  }

  int maxx = 0;
  int i = 0;
  while (i < lst.length) {
    if (lst[i] > maxx && isPrime(lst[i])) {
      maxx = lst[i];
    }
    i++;
  }

  int result = 0;
  for (var digit in maxx.toString().split('')) {
    result += int.parse(digit);
