String matchParens(List<String> lst) {
  bool check(String s) {
    int val = 0;
    for (int i = 0; i < s.length; i++) {
      if (s[i] == '(') {
        val = val + 1;
      } else {
        val = val - 1;
      }
      if (val < 0) {
        return false;
      }
    }
    return val == 0 ? true : false;
  }

  String s1 = lst[0] + lst[1];
  String s2 = lst[1] + lst[0];
