def sum_odd_in_even_position(lst):
    """Given a non-empty list of integers, return the sum of all of the odd elements that are in even positions.


    Examples
    sum_odd_in_even_position([5, 8, 7, 1]) ==> 12
    sum_odd_in_even_position([3, 3, 3, 3, 3]) ==> 9
    sum_odd_in_even_position([30, 13, 24, 321]) ==>0
    """

def solution(lst):
    return sum([x for idx, x in enumerate(lst) if idx%2==0 and x%2==1])

