@pragma('vm:entry-point')
bool isSorted(List<int> lst) {
  if (lst.isEmpty) {
    return true;
  }

  Map<int, int> countDigit = {};
  for (var i in lst) {
    countDigit[i] = 0;
  }

  for (var i in lst) {
    countDigit[i] = countDigit[i]! + 1;
  }

  for (var i in lst) {
    if (countDigit[i]! > 2) {
      return false;
    }
  }

  for (int i = 1; i < lst.length; i++) {
    if (lst[i - 1] > lst[i]) {
      return false;
    }
  }

  return true;
}

@pragma('vm:entry-point')
void main() {
  print(isSorted([5]));
  print(isSorted([1, 2, 3, 4, 5]));
  print(isSorted([1, 3, 2, 4, 5]));
  print(isSorted([1, 2, 3, 4, 5, 6]));
  print(isSorted([1, 2, 3, 4, 5, 6, 7]));
  print(isSorted([1, 3, 2, 4, 5, 6, 7]));
  print(isSorted([1, 2, 2, 3, 3, 4]));
  print(isSorted([1, 2, 2, 2, 3, 4]));
}

