@pragma('vm:entry-point')
int? prodSigns(List<int> arr) {
  if (arr.isEmpty) return null;

  int prod = arr.contains(0) 
      ? 0 
      : (arr.where((x) => x < 0).length % 2 == 0 ? 1 : -1);

  return prod * arr.map((i) => i.abs()).reduce((a, b) => a + b);
}

@pragma('vm:entry-point')
void main() {
  print(prodSigns([1, 2, 2, -4]) == -9);
  print(prodSigns([0, 1]) == 0);
  print(prodSigns([]) == null);
  print(prodSigns([1, 1, 1, 2, 3, -1, 1]) == -10);
  print(prodSigns([-1, 1, -1, 1]) == 4);
  print(prodSigns([-1, 1, 1, 1]) == -4);
  print(prodSigns([-1, 1, 1, 0]) == 0);
}

