bool checkIfLastCharIsALetter(String txt) {
  List<String> check = txt.split(' ');
  String lastPart = check[check.length - 1];

  if (lastPart.length == 1) {
    int charCode = lastPart.toLowerCase().codeUnitAt(0);
    return charCode >= 97 && charCode <= 122;
  }
  return false;
}

