@pragma('vm:entry-point')
List<dynamic> largestSmallestIntegers(List<int> lst) {
  var smallest = lst.where((x) => x < 0).toList();
  var largest = lst.where((x) => x > 0).toList();

  var maxNegative = smallest.isNotEmpty ? smallest.reduce((a, b) => a > b ? a : b) : null;
  var minPositive = largest.isNotEmpty ? largest.reduce((a, b) => a < b ? a : b) : null;

  return [maxNegative, minPositive];
}

@pragma('vm:entry-point')
void main() {
  // Test cases
  print(largestSmallestIntegers([2, 4, 1, 3, 5, 7])); // [null, 1]
  print(largestSmallestIntegers([])); // [null, null]
  print(largestSmallestIntegers([0])); // [null, null]
  print(largestSmallestIntegers([-1, -3, -5, 2, 4])); // [-1, 2]
  print(largestSmallestIntegers([-6, -4, -1])); // [-1, null]
  print(largestSmallestIntegers([1, 2, 3])); // [null, 1]
}

