@pragma('vm:entry-point')
String fileNameCheck(String fileName) {
  List<String> suf = ['txt', 'exe', 'dll'];
  List<String> lst = fileName.split('.');

  if (lst.length != 2) {
    return 'No';
  }

  if (!suf.contains(lst[1])) {
    return 'No';
  }

  if (lst[0].isEmpty) {
    return 'No';
  }

  if (!RegExp(r'^[a-zA-Z]').hasMatch(lst[0][0])) {
    return 'No';
  }

  int digitCount = lst[0].split('').where((x) => RegExp(r'[0-9]').hasMatch(x)).length;

  if (digitCount > 3) {
    return 'No';
  }

  return 'Yes';
}

@pragma('vm:entry-point')
