  print(fileNameCheck("example.txt"));
  print(fileNameCheck("1example.dll"));
  print(fileNameCheck("example"));
  print(fileNameCheck("example.doc"));
  print(fileNameCheck(".txt"));
  print(fileNameCheck("exam1234ple.txt"));
  print(fileNameCheck("exam123ple.txt"));
  print(fileNameCheck("example.exe"));
  print(fileNameCheck("example..txt"));
}

