  List<int> a = [];
  for (int i = 1; i <= n; i++) {
    a.add(i * i - i + 1);
  }

  int count = 0;
  for (int i = 0; i < n; i++) {
    for (int j = i + 1; j < n; j++) {
      for (int k = j + 1; k < n; k++) {
        if ((a[i] + a[j] + a[k]) % 3 == 0) {
